$ErrorActionPreference = 'Stop'

$Root = 'C:\GraveOps\GraveOps-Community'
$Stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$Stage = Join-Path $env:TEMP "GraveOps-2.0-RC2-stage-$Stamp"
$Rollback = Join-Path $env:TEMP "GraveOps-2.0-RC2-pre-$Stamp"
$Zip = Join-Path $env:TEMP "GraveOps-2.0-RC2-$Stamp.zip"
$ExpectedPayloadSha256 = '9FE6070C1531D0BB6AA4238714F71B2C61B2AEC0B4071A1EFCF693D41C326C27'
function Assert-Contains {
    param([string]$Path, [string]$Needle, [string]$Label)
    if (-not (Test-Path $Path)) { throw "Acceptance failed: missing $Label ($Path)" }
    $text = [IO.File]::ReadAllText($Path)
    if ($text.IndexOf($Needle, [StringComparison]::Ordinal) -lt 0) {
        throw "Acceptance failed: $Label"
    }
}

function Assert-NotContains {
    param([string]$Path, [string]$Needle, [string]$Label)
    if (-not (Test-Path $Path)) { return }
    $text = [IO.File]::ReadAllText($Path)
    if ($text.IndexOf($Needle, [StringComparison]::OrdinalIgnoreCase) -ge 0) {
        throw "Acceptance failed: $Label"
    }
}

function Restore-GraveOps {
    if (-not (Test-Path $Rollback)) { return }
    Write-Host 'Restoring pre-2.0 RC2 GraveOps source and published build...' -ForegroundColor Yellow

    foreach ($name in @('src','docs','installer','server-helpers')) {
        $target = Join-Path $Root $name
        $saved = Join-Path $Rollback $name
        Remove-Item $target -Recurse -Force -ErrorAction SilentlyContinue
        if (Test-Path $saved) { Copy-Item $saved $target -Recurse -Force }
    }

    $buildTarget = Join-Path $Root 'build-release.ps1'
    Remove-Item $buildTarget -Force -ErrorAction SilentlyContinue
    $savedBuild = Join-Path $Rollback 'build-release.ps1'
    if (Test-Path $savedBuild) { Copy-Item $savedBuild $buildTarget -Force }

    foreach ($name in @('publish','dist')) {
        $target = Join-Path $Root $name
        $saved = Join-Path $Rollback $name
        Remove-Item $target -Recurse -Force -ErrorAction SilentlyContinue
        if (Test-Path $saved) { Copy-Item $saved $target -Recurse -Force }
    }

    Write-Host 'Previous GraveOps build restored.' -ForegroundColor Green
}

Write-Host '============================================================' -ForegroundColor Magenta
Write-Host ' GRAVEOPS 2.0 RC2 - RUNTIME POLISH & CODE CLEANUP' -ForegroundColor Magenta
Write-Host ' Backups + Lifecycle fix + thread-safe history + storage cleanup + source streamlining' -ForegroundColor Magenta
Write-Host '============================================================' -ForegroundColor Magenta
Write-Host ''

try {
    if (-not (Test-Path $Root)) { throw "GraveOps source tree not found: $Root" }

    $Project = Join-Path $Root 'src\GraveOps.App\GraveOps.App.csproj'
    $Identity = Join-Path $Root 'src\GraveOps.App\ProductIdentity.cs'
    if (-not (Test-Path $Project) -or -not (Test-Path $Identity)) {
        throw 'This does not look like the current GraveOps source tree.'
    }

    Assert-Contains $Identity 'ProductName = "GraveOps"' 'GraveOps product identity'
    Assert-Contains $Identity 'CredentialNamespace = "GraveOpsCommunity"' 'upgrade-safe credential namespace'

    Get-Process -Name 'GraveOpsCommunity','GraveOps' -ErrorAction SilentlyContinue | ForEach-Object {
        try {
            if ($_.Path -and $_.Path.StartsWith($Root, [StringComparison]::OrdinalIgnoreCase)) {
                Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue
            }
            elseif ($_.ProcessName -eq 'GraveOpsCommunity') {
                Stop-Process -Id $_.Id -Force -ErrorAction SilentlyContinue
            }
        }
        catch { }
    }
    Start-Sleep -Milliseconds 350

    Remove-Item $Stage -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item $Rollback -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item $Zip -Force -ErrorAction SilentlyContinue
    New-Item -ItemType Directory -Force -Path $Stage | Out-Null
    New-Item -ItemType Directory -Force -Path $Rollback | Out-Null

    foreach ($name in @('src','docs','installer','server-helpers')) {
        $source = Join-Path $Root $name
        if (Test-Path $source) {
            Copy-Item $source (Join-Path $Rollback $name) -Recurse -Force
        }
    }

    $currentBuild = Join-Path $Root 'build-release.ps1'
    if (Test-Path $currentBuild) {
        Copy-Item $currentBuild (Join-Path $Rollback 'build-release.ps1') -Force
    }

    foreach ($name in @('publish','dist')) {
        $source = Join-Path $Root $name
        if (Test-Path $source) {
            Copy-Item $source (Join-Path $Rollback $name) -Recurse -Force
        }
    }

