'@

    [IO.File]::WriteAllBytes(
        $Zip,
        [Convert]::FromBase64String(($Payload -replace '\s','')))

    $actual = (Get-FileHash $Zip -Algorithm SHA256).Hash
    if ($actual -ne $ExpectedPayloadSha256) {
        throw "Embedded payload hash mismatch. Expected $ExpectedPayloadSha256; got $actual"
    }
    Write-Host 'PASS: embedded GraveOps 2.0 RC2 payload verified' -ForegroundColor Green

    Expand-Archive -Path $Zip -DestinationPath $Stage -Force
    # Compiler-regression gate: ActionRunner must use fully-qualified Stopwatch.
    $actionRunnerGate = Join-Path $Stage 'src\GraveOps.App\Services\ActionRunnerService.cs'

    if (-not (Test-Path $actionRunnerGate)) {
        throw "Acceptance failed: staged ActionRunnerService.cs is missing."
    }

    $actionRunnerGateText =
        [IO.File]::ReadAllText($actionRunnerGate)

    if (
        [regex]::IsMatch(
            $actionRunnerGateText,
            '(?<!System\.Diagnostics\.)\bStopwatch\b'
        )
    ) {
        throw "Acceptance failed: ActionRunnerService.cs contains an unqualified Stopwatch reference."
    }

    if (
        $actionRunnerGateText -notmatch
        'System\.Diagnostics\.Stopwatch\.StartNew\(\)'
    ) {
        throw "Acceptance failed: ActionRunnerService.cs is missing the qualified Stopwatch.StartNew() call."
    }

    Write-Host 'PASS: ActionRunner Stopwatch regression gate' -ForegroundColor Green


    $appRoot = Join-Path $Stage 'src\GraveOps.App'
    $xamlFiles = Get-ChildItem $appRoot -Filter '*.xaml' -Recurse
    if ($xamlFiles.Count -lt 30) {
        throw "Acceptance failed: expected a complete XAML surface; found only $($xamlFiles.Count) file(s)."
    }

    foreach ($xaml in $xamlFiles) {
        try {
            [xml](Get-Content $xaml.FullName -Raw) | Out-Null
        }
        catch {
            throw "XAML parse failed: $($xaml.FullName): $($_.Exception.Message)"
        }
    }
    Write-Host "PASS: all staged XAML parsed ($($xamlFiles.Count))" -ForegroundColor Green

    $buildInfo = Join-Path $appRoot 'BuildInfo.cs'
    $appXaml = Join-Path $appRoot 'App.xaml'
    $dashboard = Join-Path $appRoot 'Views\DashboardView.xaml'
    $dashboardCode = Join-Path $appRoot 'Views\DashboardView.xaml.cs'
    $lifecycle = Join-Path $appRoot 'Views\MediaLifecycleView.xaml'
    $mainWindowCode = Join-Path $appRoot 'MainWindow.xaml.cs'
    $appServices = Join-Path $appRoot 'Services\AppServices.cs'
    $activity = Join-Path $appRoot 'Services\ActivityService.cs'
    $fleetHistory = Join-Path $appRoot 'Services\FleetHistoryService.cs'
    $backupService = Join-Path $appRoot 'Services\BackupInventoryService.cs'
    $backupView = Join-Path $appRoot 'Views\BackupsView.xaml.cs'
    $storageFilter = Join-Path $appRoot 'Services\LinuxStorageFilter.cs'
    $remoteLinux = Join-Path $appRoot 'Services\Hosts\RemoteLinuxHostProvider.cs'
    $integrationRuntime = Join-Path $appRoot 'Services\IntegrationRuntimeService.cs'
    $monitor = Join-Path $appRoot 'Services\BackgroundMonitorService.cs'
    $logs = Join-Path $appRoot 'Views\LogsView.xaml.cs'
    $iss = Join-Path $Stage 'installer\GraveOps.iss'

    Assert-Contains $buildInfo 'DisplayVersion = "2.0 RC2"' '2.0 RC2 version marker'
    Assert-Contains $appXaml 'x:Key="GoStatusStrip"' 'shared Lifecycle status-strip style'
    Assert-Contains $lifecycle 'StaticResource GoStatusStrip' 'Lifecycle status-strip resource use'

    Assert-Contains $dashboard 'Text="Quick modules"' 'modular Dashboard'
    Assert-Contains $dashboard 'Tag="Backups"' 'Backups Quick Module'
    Assert-Contains $dashboard 'Click="Backups_Click"' 'Dashboard Backups entry point'
    Assert-Contains $dashboardCode 'ApplyQuickModulePreferences' 'Quick Module preferences'
    Assert-NotContains $dashboard 'Compatibility sink' 'obsolete Dashboard compatibility sink remains'

    Assert-Contains $mainWindowCode 'BackupsNav.Visibility = V(hasTarget);' 'capability-aware Backups navigation'
    Assert-Contains $appServices 'BackupInventoryService' 'provider-neutral backup inventory service'
    Assert-Contains $appServices 'Migrate20Rc2' 'RC2 configuration migration'
    Assert-Contains $backupService 'HostConnectionKind.RemoteLinux' 'Linux backup inventory provider'
    Assert-Contains $backupService 'HostConnectionKind.RemoteWindows' 'Remote Windows backup inventory provider'
    Assert-Contains $backupService 'HostConnectionKind.LocalWindows' 'Local Windows backup inventory provider'
    Assert-NotContains $backupView '.StdOut' 'Backups view still depends on transport-specific command results'

    Assert-Contains $activity 'UiDispatcher.Invoke' 'thread-safe Activity collection updates'
    Assert-Contains $fleetHistory 'UiDispatcher.Invoke' 'thread-safe Fleet History collection updates'
    Assert-Contains $fleetHistory 'item.Component.Equals("Host"' 'fleet-state host-index rebuild fix'

    Assert-Contains $storageFilter 'PseudoFileSystems' 'Linux pseudo-filesystem filtering'
    Assert-Contains $remoteLinux 'LinuxStorageFilter.IsMeaningful' 'Remote Linux storage filtering'

    Assert-Contains $integrationRuntime '--preview' 'Recyclarr preview safety'
    Assert-Contains $logs 'HostConnectionKind.RemoteWindows' 'Remote Windows Log Center'
    Assert-Contains $iss '0C406F81-B8B5-4C27-922B-C2B38C9A1E5E' 'stable installer identity'

    # Frozen RC2 packaging regressions.
    $stagedBuildRelease = Join-Path $Stage 'build-release.ps1'
    Assert-Contains $stagedBuildRelease "LOCALAPPDATA 'Programs\Inno Setup 6\ISCC.exe'" 'per-user Inno Setup discovery'
    Assert-Contains $stagedBuildRelease "Get-Command 'ISCC.exe'" 'PATH Inno Setup discovery fallback'
    Assert-Contains $iss 'UninstallDisplayIcon={app}\{#MyAppExeName}' 'installer uninstall icon metadata'
    Assert-Contains $iss 'VersionInfoVersion=2.0.0.0' 'numeric installer file version'
    Assert-Contains $iss 'VersionInfoProductVersion=2.0.0.0' 'numeric installer product version'
    Assert-Contains $iss 'VersionInfoProductTextVersion={#MyAppVersion}' 'RC2 textual installer version'
    Assert-Contains $iss 'CloseApplications=yes' 'installer close-running-app policy'
    Assert-Contains $iss 'RestartApplications=no' 'installer no-restart-app policy'
    Write-Host 'PASS: RC2 frozen packaging regression gate' -ForegroundColor Green

    foreach ($removed in @(
        'Services\FullHealthSnapshotHub.cs',
        'Services\HealthParser.cs',
        'Services\CommunityIntegrationService.cs',
        'Models\CommunityIntegrationModels.cs',
        'Models\HealthModels.cs',
        'Views\CommunityIntegrationView.xaml',
        'Views\CommunityIntegrationView.xaml.cs',
        'Views\ControlPlaneIntelligenceWindow.xaml',
        'Views\ControlPlaneIntelligenceWindow.xaml.cs'
    )) {
        if (Test-Path (Join-Path $appRoot $removed)) {
            throw "Acceptance failed: obsolete source remains: $removed"
        }
    }

    foreach ($required in @(
        'Services\IntegrationRuntimeService.cs',
        'Models\IntegrationRuntimeModels.cs',
        'Models\CommandModels.cs',
        'Services\UiDispatcher.cs',
        'Services\BackupInventoryService.cs',
        'Models\BackupModels.cs'
    )) {
        if (-not (Test-Path (Join-Path $appRoot $required))) {
            throw "Acceptance failed: required RC2 source missing: $required"
        }
    }

    $forbidden = @('gravetypebed','Plerver','/opt/dumb')
    $scanFiles = Get-ChildItem $appRoot -File -Recurse |
        Where-Object { $_.Extension -in @('.cs','.xaml','.json') }

    foreach ($file in $scanFiles) {
        $sourceText = [IO.File]::ReadAllText($file.FullName)
        foreach ($needle in $forbidden) {
            if ($sourceText.IndexOf($needle, [StringComparison]::OrdinalIgnoreCase) -ge 0) {
                throw "Acceptance failed: personal assumption '$needle' remains in application source: $($file.FullName)"
            }
        }
    }

    $obsoleteSymbols = @(
        'FullHealthSnapshotHub',
        'HealthParser',
        'CommunityIntegrationService',
        'CommunityIntegrationStatus',
        'CommunityIntegrationView',
        'ControlPlaneIntelligenceWindow',
        'UseSudoNonInteractive',
        'DashboardHideRecommendations',
        'DashboardHideConnectivity',
        'DashboardSwapIntelligence',
        'MaintenanceReason'
    )

    foreach ($file in $scanFiles) {
        $sourceText = [IO.File]::ReadAllText($file.FullName)
        foreach ($needle in $obsoleteSymbols) {
            if ($sourceText.IndexOf($needle, [StringComparison]::Ordinal) -ge 0) {
                throw "Acceptance failed: obsolete symbol '$needle' remains in application source: $($file.FullName)"
            }
        }
    }

    if ((Get-Content $monitor -Raw).Contains('graveopsctl')) {
        throw 'Acceptance failed: background monitor still depends on graveopsctl.'
    }

    # Regression gates from RC1 compiler failures.
    $updateCenter = Get-Content (Join-Path $appRoot 'Views\UpdateCenterView.xaml.cs') -Raw
    $setupWizard = Get-Content (Join-Path $appRoot 'Views\SetupWizardWindow.xaml.cs') -Raw
    $remoteDiscovery = Get-Content (Join-Path $appRoot 'Services\RemoteWindowsDiscoveryService.cs') -Raw

    if ($updateCenter.Contains('.DockerAvailable') -or
        $updateCenter.Contains('.RunningContainerCount') -or
        $updateCenter.Contains('host?.Applications')) {
        throw 'Acceptance failed: Update Center still references obsolete RC model members.'
    }

    Assert-Contains (Join-Path $appRoot 'Views\ServersView.xaml.cs') '"Remote Windows verified discovery");' 'Remote Windows server discovery assignment'
    Assert-Contains (Join-Path $appRoot 'Views\SetupWizardWindow.xaml.cs') 'var verifiedNames = discovery.Count == 0' 'Remote Windows setup discovery list handling'
    Assert-Contains (Join-Path $appRoot 'Views\SetupWizardWindow.xaml.cs') 'var verifiedNames = discovery.Integrations.Count == 0' 'Remote Linux setup discovery wrapper handling'
    Assert-Contains (Join-Path $appRoot 'Views\SetupWizardWindow.xaml.cs') 'discovery.Integrations.Select(x => x.DisplayName)' 'Remote Linux integration name projection'

    if ($remoteDiscovery.Contains('signature.Port is { } port && ports.Contains(port)')) {
        throw 'Acceptance failed: Remote Windows discovery still contains the port-local collision.'
    }

    Assert-Contains $integrationRuntime 'localPreviewOutput' 'Recyclarr local preview variable isolation'
    Assert-Contains $integrationRuntime 'remotePreviewOutput' 'Recyclarr remote preview variable isolation'
    Assert-Contains $integrationRuntime 'remoteRuntimeProbe' 'Recyclarr remote runtime variable isolation'

    Write-Host 'PASS: RC2 runtime fixes, cleanup, safety, shareability and prior compiler-regression gates accepted' -ForegroundColor Green

    foreach ($name in @('src','docs','installer','server-helpers')) {
        $target = Join-Path $Root $name
        Remove-Item $target -Recurse -Force -ErrorAction SilentlyContinue
        $staged = Join-Path $Stage $name
        if (Test-Path $staged) {
            Copy-Item $staged $target -Recurse -Force
        }
    }

    Copy-Item (Join-Path $Stage 'build-release.ps1') (Join-Path $Root 'build-release.ps1') -Force

    Write-Host ''
    Write-Host 'Building GraveOps 2.0 RC2...' -ForegroundColor Magenta
    & (Join-Path $Root 'build-release.ps1')
    if ($LASTEXITCODE -ne 0) {
        throw "build-release.ps1 failed with exit code $LASTEXITCODE"
    }

    $Exe = Join-Path $Root 'publish\win-x64\GraveOps.exe'
    if (-not (Test-Path $Exe)) {
        throw "Build succeeded but executable was not found: $Exe"
    }

    Get-ChildItem (Join-Path $Root 'src') -Directory -Recurse -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -in @('bin','obj') } |
        Sort-Object FullName -Descending |
        Remove-Item -Recurse -Force -ErrorAction SilentlyContinue

    Remove-Item $Rollback -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item $Stage -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item $Zip -Force -ErrorAction SilentlyContinue

    Write-Host ''
    Write-Host '============================================================' -ForegroundColor Green
    Write-Host ' GRAVEOPS 2.0 RC2 BUILD SUCCEEDED' -ForegroundColor Green
    Write-Host '============================================================' -ForegroundColor Green
    Write-Host "GraveOps tree: $Root"
    Write-Host "Run: $Exe"

    $setup = Join-Path $Root 'dist\GraveOps-Setup-2.0-RC2.exe'
    if (Test-Path $setup) {
        Write-Host "Setup: $setup"
    }

    Write-Host 'Backups is restored as a provider-neutral first-class surface and Dashboard module.'
    Write-Host 'Lifecycle resource resolution, fleet-history UI threading and Linux storage filtering are corrected.'
    Write-Host 'Obsolete hidden health compatibility code, dead members and legacy internal integration type names were removed.'
    Write-Host 'Recyclarr remains preview-only; no sync/write action is exposed.'
    Write-Host 'Temporary rollback removed; no historical build was retained.'
    Write-Host 'Personal GraveOps V1.2.2 was not touched.'
}
catch {
    Write-Host ''
    Write-Host 'ERROR: GraveOps 2.0 RC2 failed.' -ForegroundColor Red
    Restore-GraveOps
    Remove-Item $Stage -Recurse -Force -ErrorAction SilentlyContinue
    Remove-Item $Zip -Force -ErrorAction SilentlyContinue
    throw
}


